//! C ABI for the com0com SDK (`com0com_capi`).
//!
//! All exported types are `#[repr(C)]` PODs with fixed-size buffers: callers
//! allocate, the library never returns a string that must be freed. Lists use
//! the `(out, cap, *count)` convention and report `C0C_E_BUFFER_TOO_SMALL`
//! with the required count when the buffer is too small.
//!
//! The header at `include/com0com_capi.h` is generated by `tools/header-gen`
//! from the constants and layout below; do not edit it by hand.

#![allow(non_camel_case_types)]
// The generated C header is the public contract for these exports; pointer
// validity is identical for every entry point and documented there.
#![allow(clippy::missing_safety_doc)]

use std::ffi::{c_char, c_void, CStr};
use std::mem::size_of;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::ptr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use com0com_core::{
    DriverKind, DriverStatus, Event, EventFilter, EventSubscription, FlowControl, LogLevel,
    PairParams, Parity, PinWiring, PortConfig, PortName, RecvError, RestoreOptions, SdkError,
    StopBits,
};
use com0com_sdk::{Monitor, Sdk};

/// ABI version reported through `c0c_api_version`.
pub const C0C_API_VERSION: u32 = 1;

pub const C0C_OK: i32 = 0;
pub const C0C_E_INVALID_ARGUMENT: i32 = -1;
pub const C0C_E_NOT_FOUND: i32 = -2;
pub const C0C_E_ALREADY_EXISTS: i32 = -3;
pub const C0C_E_BUSY: i32 = -4;
pub const C0C_E_PERMISSION: i32 = -5;
pub const C0C_E_UNSUPPORTED: i32 = -6;
pub const C0C_E_DRIVER_UNAVAILABLE: i32 = -7;
pub const C0C_E_IO: i32 = -8;
pub const C0C_E_TIMEOUT: i32 = -9;
pub const C0C_E_DAEMON_UNAVAILABLE: i32 = -10;
pub const C0C_E_PROTOCOL: i32 = -11;
pub const C0C_E_BUFFER_TOO_SMALL: i32 = -12;
pub const C0C_E_PANIC: i32 = -13;

/// Backend selector for [`c0c_open`].
pub const C0C_BACKEND_AUTO: i32 = 0;
pub const C0C_BACKEND_NATIVE: i32 = 1;
pub const C0C_BACKEND_DAEMON: i32 = 2;
/// In-memory backend, available only when the library is built with the
/// `fake` feature (the smoke tests use it).
pub const C0C_BACKEND_FAKE: i32 = 3;

pub const C0C_PAIR_ID_AUTO: i32 = -1;
pub const C0C_NO_PAIR: u32 = u32::MAX;
pub const C0C_TIMEOUT_NONE: u32 = u32::MAX;

pub const C0C_EVENT_PAIR_ADDED: i32 = 0;
pub const C0C_EVENT_PAIR_REMOVED: i32 = 1;
pub const C0C_EVENT_PARAMS_CHANGED: i32 = 2;
pub const C0C_EVENT_DRIVER_STATUS_CHANGED: i32 = 3;

pub const C0C_DRIVER_BUS: i32 = 0;
pub const C0C_DRIVER_PORT: i32 = 1;

pub const C0C_DRIVER_RUNNING: i32 = 0;
pub const C0C_DRIVER_STOPPED: i32 = 1;
pub const C0C_DRIVER_START_PENDING: i32 = 2;
pub const C0C_DRIVER_STOP_PENDING: i32 = 3;
pub const C0C_DRIVER_NOT_INSTALLED: i32 = 4;
pub const C0C_DRIVER_UNKNOWN: i32 = 5;

pub const C0C_LOG_ERROR: i32 = 0;
pub const C0C_LOG_WARNING: i32 = 1;
pub const C0C_LOG_INFORMATION: i32 = 2;
pub const C0C_LOG_VERBOSE: i32 = 3;
