pub const C0C_PORT_NAME_MAX: usize = 32;
pub const C0C_PATH_MAX: usize = 256;
pub const C0C_MESSAGE_MAX: usize = 256;
pub const C0C_SERVICE_NAME_MAX: usize = 64;
pub const C0C_VERSION_MAX: usize = 32;
