pub const C0C_TIMESTAMP_MAX: usize = 40;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct c0c_open_options {
    /// `sizeof(c0c_open_options)` from the caller's compiler.
    pub size: u32,
    pub backend: i32,
    /// Daemon endpoint (UTF-8, NUL-terminated); ignored unless
    /// `backend == C0C_BACKEND_DAEMON`. May be null for the default endpoint.
    pub endpoint: *const c_char,
}

impl Default for c0c_open_options {
    fn default() -> Self {
        Self {
            size: size_of::<Self>() as u32,
            backend: C0C_BACKEND_AUTO,
            endpoint: ptr::null(),
        }
    }
}

