/// Opaque session handle (`void`-like from C).
pub struct c0c_session {
    inner: Mutex<SessionInner>,
}

struct SessionInner {
    sdk: Sdk,
    last: c0c_error,
}

impl c0c_session {
    fn new(sdk: Sdk) -> Self {
        Self {
            inner: Mutex::new(SessionInner {
                sdk,
                last: c0c_error::default(),
            }),
        }
    }
}

/// Opaque event subscription handle.
pub struct c0c_subscription {
    stop: Arc<AtomicBool>,
    join: Mutex<Option<JoinHandle<()>>>,
    thread: thread::ThreadId,
}

/// Opaque serial monitor handle.
pub struct c0c_monitor {
    inner: Mutex<MonitorInner>,
}

struct MonitorInner {
    monitor: Monitor,
    pending: Vec<u8>,
}

#[derive(Clone, Copy)]
struct UserPtr(*mut c_void);

// The caller passes this pointer back to the callback unchanged; the event
// thread only copies it around and never dereferences it.
unsafe impl Send for UserPtr {}

#[derive(Clone, Debug)]
struct CError {
    code: i32,
    win32: u32,
    message: String,
}

impl CError {
    fn new(code: i32, message: impl Into<String>) -> Self {
        Self {
            code,
            win32: 0,
            message: message.into(),
        }
    }

    fn from_sdk(error: &SdkError) -> Self {
        let message = error.to_string();
        let win32 = error.win32_code().unwrap_or(0);
        let code = match error {
            SdkError::Unsupported => C0C_E_UNSUPPORTED,
            SdkError::PermissionDenied => C0C_E_PERMISSION,
            SdkError::DriverUnavailable => C0C_E_DRIVER_UNAVAILABLE,
            SdkError::NotFound => C0C_E_NOT_FOUND,
            SdkError::AlreadyExists => C0C_E_ALREADY_EXISTS,
            SdkError::InvalidArgument(_) => C0C_E_INVALID_ARGUMENT,
            SdkError::Busy => C0C_E_BUSY,
            SdkError::Io(_) | SdkError::Win32 { .. } | SdkError::Internal(_) => C0C_E_IO,
            SdkError::Timeout => C0C_E_TIMEOUT,
            SdkError::DaemonUnavailable => C0C_E_DAEMON_UNAVAILABLE,
            SdkError::Protocol(_) => C0C_E_PROTOCOL,
        };
        Self {
            code,
            win32,
            message,
        }
    }

    fn public(&self) -> c0c_error {
        let mut out = c0c_error {
            code: self.code,
            win32: self.win32,
            ..c0c_error::default()
        };
        write_str(&mut out.message, &self.message);
        out
    }
}

fn invalid(message: impl Into<String>) -> CError {
    CError::new(C0C_E_INVALID_ARGUMENT, message)
}

fn write_str<const N: usize>(dst: &mut [c_char; N], value: &str) {
    let bytes = value.as_bytes();
    let len = bytes.len().min(N.saturating_sub(1));
    for (slot, byte) in dst.iter_mut().zip(bytes.iter()).take(len) {
        *slot = *byte as c_char;
    }
    dst[len] = 0;
}

// c_char is i8 on Windows and u8 on Unix: the cast is required on Windows
// and a no-op on Unix, where clippy would flag it.
#[allow(clippy::unnecessary_cast)]
fn read_str(buf: &[c_char]) -> Result<String, CError> {
    let len = buf.iter().position(|c| *c == 0).unwrap_or(buf.len());
    let bytes: Vec<u8> = buf[..len].iter().map(|c| *c as u8).collect();
    String::from_utf8(bytes).map_err(|_| invalid("string is not valid UTF-8"))
}

fn c_str(value: *const c_char, what: &str) -> Result<String, CError> {
    if value.is_null() {
        return Err(invalid(format!("{what} must not be null")));
    }
    unsafe { CStr::from_ptr(value) }
        .to_str()
        .map(str::to_string)
        .map_err(|_| invalid(format!("{what} is not valid UTF-8")))
}

fn parity_to_c(value: Parity) -> i32 {
    match value {
        Parity::None => 0,
        Parity::Odd => 1,
        Parity::Even => 2,
        Parity::Mark => 3,
        Parity::Space => 4,
    }
}

fn parity_from_c(value: i32) -> Result<Parity, CError> {
    match value {
        0 => Ok(Parity::None),
        1 => Ok(Parity::Odd),
        2 => Ok(Parity::Even),
        3 => Ok(Parity::Mark),
        4 => Ok(Parity::Space),
        other => Err(invalid(format!("unknown parity {other}"))),
    }
}

fn stop_bits_to_c(value: StopBits) -> i32 {
    match value {
        StopBits::One => 0,
        StopBits::OnePointFive => 1,
        StopBits::Two => 2,
    }
}

fn stop_bits_from_c(value: i32) -> Result<StopBits, CError> {
    match value {
        0 => Ok(StopBits::One),
        1 => Ok(StopBits::OnePointFive),
        2 => Ok(StopBits::Two),
        other => Err(invalid(format!("unknown stop bits {other}"))),
    }
}

fn flow_control_to_c(value: FlowControl) -> i32 {
    match value {
        FlowControl::None => 0,
        FlowControl::RtsCts => 1,
        FlowControl::XonXoff => 2,
        FlowControl::DtrDsr => 3,
    }
}

fn flow_control_from_c(value: i32) -> Result<FlowControl, CError> {
    match value {
        0 => Ok(FlowControl::None),
        1 => Ok(FlowControl::RtsCts),
        2 => Ok(FlowControl::XonXoff),
        3 => Ok(FlowControl::DtrDsr),
        other => Err(invalid(format!("unknown flow control {other}"))),
    }
}

fn duration_to_ms(value: Option<Duration>) -> u32 {
    value
        .map(|duration| duration.as_millis().min(u32::MAX as u128) as u32)
        .unwrap_or(C0C_TIMEOUT_NONE)
}

fn ms_to_duration(value: u32) -> Option<Duration> {
    (value != C0C_TIMEOUT_NONE).then(|| Duration::from_millis(value as u64))
}

fn driver_kind_from_c(value: i32) -> Result<DriverKind, CError> {
    match value {
        C0C_DRIVER_BUS => Ok(DriverKind::Bus),
        C0C_DRIVER_PORT => Ok(DriverKind::Port),
        other => Err(invalid(format!("unknown driver kind {other}"))),
    }
}

fn driver_kind_to_c(value: DriverKind) -> i32 {
    match value {
        DriverKind::Bus => C0C_DRIVER_BUS,
        DriverKind::Port => C0C_DRIVER_PORT,
    }
}

fn driver_status_to_c(value: DriverStatus) -> i32 {
    match value {
        DriverStatus::Running => C0C_DRIVER_RUNNING,
        DriverStatus::Stopped => C0C_DRIVER_STOPPED,
        DriverStatus::StartPending => C0C_DRIVER_START_PENDING,
        DriverStatus::StopPending => C0C_DRIVER_STOP_PENDING,
        DriverStatus::NotInstalled => C0C_DRIVER_NOT_INSTALLED,
        DriverStatus::Unknown => C0C_DRIVER_UNKNOWN,
    }
}

fn log_level_to_c(value: LogLevel) -> i32 {
    match value {
        LogLevel::Error => C0C_LOG_ERROR,
        LogLevel::Warning => C0C_LOG_WARNING,
        LogLevel::Information => C0C_LOG_INFORMATION,
        LogLevel::Verbose => C0C_LOG_VERBOSE,
        LogLevel::Unknown => C0C_LOG_UNKNOWN,
    }
}

impl From<&PairParams> for c0c_params {
    fn from(value: &PairParams) -> Self {
        let mut out = Self::default();
        write_str(&mut out.port_a, value.port_a.as_str());
        write_str(&mut out.port_b, value.port_b.as_str());
        out.baud_emu = value.baud_emu as u32;
        out.overrun = value.overrun as u32;
        out.noise_enabled = value.noise_enabled as u32;
        out.noise_probability = value.noise_probability as u32;
        out.exclusive = value.exclusive as u32;
        out.plugin = value.plugin as u32;
        out.pin_wiring_a = value.pin_wiring_a.lines;
        out.pin_wiring_b = value.pin_wiring_b.lines;
        out
    }
}

fn pair_info(id: u8, params: &PairParams) -> c0c_pair_info {
    let mut out = c0c_pair_info {
        id: id as u32,
        ..c0c_pair_info::default()
    };
    write_str(&mut out.port_a, params.port_a.as_str());
    write_str(&mut out.port_b, params.port_b.as_str());
    out.baud_emu = params.baud_emu as u32;
    out.overrun = params.overrun as u32;
    out.noise_enabled = params.noise_enabled as u32;
    out.noise_probability = params.noise_probability as u32;
    out.exclusive = params.exclusive as u32;
    out.plugin = params.plugin as u32;
    out.pin_wiring_a = params.pin_wiring_a.lines;
    out.pin_wiring_b = params.pin_wiring_b.lines;
    out
}

fn params_from_c(value: &c0c_params) -> Result<PairParams, CError> {
    let params = PairParams {
        port_a: PortName::new(read_str(&value.port_a)?).map_err(|e| CError::from_sdk(&e))?,
        port_b: PortName::new(read_str(&value.port_b)?).map_err(|e| CError::from_sdk(&e))?,
        baud_emu: value.baud_emu != 0,
        overrun: value.overrun != 0,
        noise_enabled: value.noise_enabled != 0,
        noise_probability: u16::try_from(value.noise_probability)
            .map_err(|_| invalid("noise_probability is outside 0..=10000"))?,
        exclusive: value.exclusive != 0,
        plugin: value.plugin != 0,
        pin_wiring_a: PinWiring {
            lines: value.pin_wiring_a,
        },
        pin_wiring_b: PinWiring {
            lines: value.pin_wiring_b,
        },
    };
    params.validate().map_err(|e| CError::from_sdk(&e))?;
    Ok(params)
}

fn port_config_from_c(value: &c0c_port_config) -> Result<PortConfig, CError> {
    let config = PortConfig {
        baud_rate: value.baud_rate,
        data_bits: u8::try_from(value.data_bits).map_err(|_| invalid("data_bits is invalid"))?,
        parity: parity_from_c(value.parity)?,
        stop_bits: stop_bits_from_c(value.stop_bits)?,
        flow_control: flow_control_from_c(value.flow_control)?,
        read_timeout: ms_to_duration(value.read_timeout_ms),
        write_timeout: ms_to_duration(value.write_timeout_ms),
    };
    config.validate().map_err(|e| CError::from_sdk(&e))?;
    Ok(config)
}

fn restore_options_from_c(value: &c0c_restore_options) -> RestoreOptions {
    RestoreOptions {
        dry_run: value.dry_run != 0,
        remove_extra: value.remove_extra != 0,
        continue_on_error: value.continue_on_error != 0,
    }
}

fn with_session<F>(session: *const c0c_session, op: F) -> i32
where
    F: FnOnce(&mut SessionInner) -> Result<(), CError>,
{
    if session.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let session = unsafe { &*session };
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut inner = session
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match op(&mut inner) {
            Ok(()) => {
                inner.last = c0c_error::default();
                C0C_OK
            }
            Err(error) => {
                inner.last = error.public();
                error.code
            }
        }
    }));
    match result {
        Ok(code) => code,
        Err(_) => {
            let mut inner = session
                .inner
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            inner.last = CError::new(C0C_E_PANIC, "panic crossed the C ABI").public();
            C0C_E_PANIC
        }
    }
}

fn store_last(session: *const c0c_session, error: &CError) {
    if session.is_null() {
        return;
    }
    let session = unsafe { &*session };
    let mut inner = session
        .inner
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    inner.last = error.public();
}

fn open_session(options: *const c0c_open_options) -> Result<c0c_session, CError> {
    let (backend, endpoint) = if options.is_null() {
        (C0C_BACKEND_AUTO, None)
    } else {
        let options = unsafe { &*options };
        if (options.size as usize) < size_of::<c0c_open_options>() {
            return Err(invalid(format!(
                "open options size {} is smaller than {}",
                options.size,
                size_of::<c0c_open_options>()
            )));
        }
        let endpoint = if options.endpoint.is_null() {
            None
        } else {
            Some(c_str(options.endpoint, "endpoint")?)
        };
        (options.backend, endpoint)
    };
    let sdk = match backend {
        C0C_BACKEND_AUTO | C0C_BACKEND_NATIVE => Sdk::open(),
        C0C_BACKEND_DAEMON => Sdk::connect_daemon(endpoint.as_deref()),
        C0C_BACKEND_FAKE => open_fake(),
        other => Err(SdkError::InvalidArgument(format!(
            "unknown backend selector {other}"
        ))),
    }
    .map_err(|error| CError::from_sdk(&error))?;
    Ok(c0c_session::new(sdk))
}

#[cfg(feature = "fake")]
fn open_fake() -> Result<Sdk, SdkError> {
    Ok(Sdk::with_backend(Arc::new(com0com_sdk::FakeBackend::new())))
}

#[cfg(not(feature = "fake"))]
fn open_fake() -> Result<Sdk, SdkError> {
    Err(SdkError::Unsupported)
}

/// Return the ABI version understood by this library.
#[no_mangle]
pub unsafe extern "C" fn c0c_api_version() -> u32 {
    C0C_API_VERSION
}

/// Open a session. `out` receives the handle on success.
#[no_mangle]
pub unsafe extern "C" fn c0c_open(
    options: *const c0c_open_options,
    out: *mut *mut c0c_session,
) -> i32 {
    if out.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *out = ptr::null_mut();
    }
    match catch_unwind(AssertUnwindSafe(|| open_session(options))) {
        Ok(Ok(session)) => {
            unsafe {
                *out = Box::into_raw(Box::new(session));
            }
            C0C_OK
        }
        Ok(Err(error)) => error.code,
        Err(_) => C0C_E_PANIC,
    }
}

/// Close a session. Every monitor and subscription must be closed first.
#[no_mangle]
pub unsafe extern "C" fn c0c_close(session: *mut c0c_session) {
    if !session.is_null() {
        unsafe {
            drop(Box::from_raw(session));
        }
    }
}

/// List pairs. `*count` receives the total; a short buffer returns
/// `C0C_E_BUFFER_TOO_SMALL` and is filled with as many entries as fit.
#[no_mangle]
pub unsafe extern "C" fn c0c_list_pairs(
    session: *const c0c_session,
    out: *mut c0c_pair_info,
    cap: usize,
    count: *mut usize,
) -> i32 {
    if count.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *count = 0;
    }
    with_session(session, |inner| {
        let pairs = inner.sdk.list_pairs().map_err(|e| CError::from_sdk(&e))?;
        unsafe {
            *count = pairs.len();
        }
        let take = cap.min(pairs.len());
        if take > 0 && out.is_null() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", pairs.len()),
            ));
        }
        for (index, pair) in pairs.iter().take(take).enumerate() {
            unsafe {
                out.add(index).write(pair_info(pair.id, &pair.params));
            }
        }
        if take < pairs.len() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", pairs.len()),
            ));
        }
        Ok(())
    })
}

/// Create a pair. `id` is [`C0C_PAIR_ID_AUTO`] or `0..=63`; `out` may be null.
#[no_mangle]
pub unsafe extern "C" fn c0c_create_pair(
    session: *const c0c_session,
    id: i32,
    params: *const c0c_params,
    out: *mut c0c_pair_info,
) -> i32 {
    if params.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let params = unsafe { &*params };
    with_session(session, |inner| {
        let params = params_from_c(params)?;
        let pair_id = if id == C0C_PAIR_ID_AUTO {
            None
        } else {
            Some(u8::try_from(id).map_err(|_| invalid("pair id is outside 0..=63"))?)
        };
        let pair = inner
            .sdk
            .create_pair(pair_id, &params)
            .map_err(|e| CError::from_sdk(&e))?;
        if !out.is_null() {
            unsafe {
                *out = pair_info(pair.id, &pair.params);
            }
        }
        Ok(())
    })
}

/// Remove a pair.
#[no_mangle]
pub unsafe extern "C" fn c0c_remove_pair(session: *const c0c_session, id: u32) -> i32 {
    with_session(session, |inner| {
        let id = u8::try_from(id).map_err(|_| invalid("pair id is outside 0..=63"))?;
        inner.sdk.delete_pair(id).map_err(|e| CError::from_sdk(&e))
    })
}

/// Read the full parameter set of one pair.
#[no_mangle]
pub unsafe extern "C" fn c0c_get_params(
    session: *const c0c_session,
    id: u32,
    out: *mut c0c_params,
) -> i32 {
    if out.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    with_session(session, |inner| {
        let id = u8::try_from(id).map_err(|_| invalid("pair id is outside 0..=63"))?;
        let params = inner.sdk.get_params(id).map_err(|e| CError::from_sdk(&e))?;
        unsafe {
            *out = c0c_params::from(&params);
        }
        Ok(())
    })
}

/// Replace the full parameter set of one pair.
#[no_mangle]
pub unsafe extern "C" fn c0c_set_params(
    session: *const c0c_session,
    id: u32,
    params: *const c0c_params,
) -> i32 {
    if params.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let params = unsafe { &*params };
    with_session(session, |inner| {
        let id = u8::try_from(id).map_err(|_| invalid("pair id is outside 0..=63"))?;
        let params = params_from_c(params)?;
        inner
            .sdk
            .set_params(id, &params)
            .map_err(|e| CError::from_sdk(&e))
    })
}

/// List ports that applications can open.
#[no_mangle]
pub unsafe extern "C" fn c0c_list_ports(
    session: *const c0c_session,
    out: *mut c0c_port_info,
    cap: usize,
    count: *mut usize,
) -> i32 {
    if count.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *count = 0;
    }
    with_session(session, |inner| {
        let ports = inner.sdk.list_ports().map_err(|e| CError::from_sdk(&e))?;
        unsafe {
            *count = ports.len();
        }
        let take = cap.min(ports.len());
        if take > 0 && out.is_null() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", ports.len()),
            ));
        }
        for (index, port) in ports.iter().take(take).enumerate() {
            let mut info = c0c_port_info {
                pair_id: port.pair_id.map(i32::from).unwrap_or(-1),
                port_index: port.port_index.map(i32::from).unwrap_or(-1),
                managed: port.managed as u32,
                ..c0c_port_info::default()
            };
            write_str(&mut info.name, &port.name);
            unsafe {
                out.add(index).write(info);
            }
        }
        if take < ports.len() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", ports.len()),
            ));
        }
        Ok(())
    })
}

/// Query driver/service information.
#[no_mangle]
pub unsafe extern "C" fn c0c_driver_info(
    session: *const c0c_session,
    kind: i32,
    out: *mut c0c_driver_desc,
) -> i32 {
    if out.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    with_session(session, |inner| {
        let kind = driver_kind_from_c(kind)?;
        let info = inner
            .sdk
            .driver_info(kind)
            .map_err(|e| CError::from_sdk(&e))?;
        let mut pod = c0c_driver_desc {
            kind: driver_kind_to_c(info.kind),
            status: driver_status_to_c(info.status),
            ..c0c_driver_desc::default()
        };
        write_str(&mut pod.service_name, &info.service_name);
        write_str(
            &mut pod.image_path,
            info.image_path.as_deref().unwrap_or(""),
        );
        write_str(&mut pod.version, info.version.as_deref().unwrap_or(""));
        write_str(&mut pod.sha256, info.sha256.as_deref().unwrap_or(""));
        unsafe {
            *out = pod;
        }
        Ok(())
    })
}

/// Read up to `limit` driver log entries.
#[no_mangle]
pub unsafe extern "C" fn c0c_driver_logs(
    session: *const c0c_session,
    limit: u32,
    out: *mut c0c_log_entry,
    cap: usize,
    count: *mut usize,
) -> i32 {
    if count.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *count = 0;
    }
    with_session(session, |inner| {
        let logs = inner
            .sdk
            .driver_logs(limit as usize)
            .map_err(|e| CError::from_sdk(&e))?;
        unsafe {
            *count = logs.len();
        }
        let take = cap.min(logs.len());
        if take > 0 && out.is_null() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", logs.len()),
            ));
        }
        for (index, entry) in logs.iter().take(take).enumerate() {
            let mut pod = c0c_log_entry {
                level: log_level_to_c(entry.level),
                ..c0c_log_entry::default()
            };
            write_str(&mut pod.timestamp, &entry.timestamp);
            write_str(&mut pod.message, &entry.message);
            unsafe {
                out.add(index).write(pod);
            }
        }
        if take < logs.len() {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {} entries", logs.len()),
            ));
        }
        Ok(())
    })
}

fn emit_event(
    callback: unsafe extern "C" fn(*mut c_void, *const c0c_event),
    user: *mut c_void,
    event: &Event,
) {
    match event {
        Event::PairAdded { pair } => {
            let params = c0c_params::from(&pair.params);
            let pod = c0c_event {
                kind: C0C_EVENT_PAIR_ADDED,
                pair_id: pair.id as u32,
                params: &params,
                driver_kind: -1,
                driver_status: -1,
            };
            unsafe {
                callback(user, &pod);
            }
        }
        Event::ParamsChanged { pair } => {
            let params = c0c_params::from(&pair.params);
            let pod = c0c_event {
                kind: C0C_EVENT_PARAMS_CHANGED,
                pair_id: pair.id as u32,
                params: &params,
                driver_kind: -1,
                driver_status: -1,
            };
            unsafe {
                callback(user, &pod);
            }
        }
        Event::PairRemoved { id } => {
            let pod = c0c_event {
                kind: C0C_EVENT_PAIR_REMOVED,
                pair_id: *id as u32,
                params: ptr::null(),
                driver_kind: -1,
                driver_status: -1,
            };
            unsafe {
                callback(user, &pod);
            }
        }
        Event::DriverStatusChanged { driver, status } => {
            let pod = c0c_event {
                kind: C0C_EVENT_DRIVER_STATUS_CHANGED,
                pair_id: C0C_NO_PAIR,
                params: ptr::null(),
                driver_kind: driver_kind_to_c(*driver),
                driver_status: driver_status_to_c(*status),
            };
            unsafe {
                callback(user, &pod);
            }
        }
    }
}

fn event_loop(
    subscription: EventSubscription,
    stop: Arc<AtomicBool>,
    callback: unsafe extern "C" fn(*mut c_void, *const c0c_event),
    user: UserPtr,
) {
    while !stop.load(Ordering::SeqCst) {
        match subscription.recv_timeout(Duration::from_millis(50)) {
            Ok(event) => emit_event(callback, user.0, &event),
            Err(RecvError::Timeout) => {}
            Err(RecvError::Empty) => thread::yield_now(),
            Err(RecvError::Disconnected) => break,
        }
    }
}

/// Subscribe to all SDK events. The callback runs on a library thread; the
/// event and its `params` pointer are valid only during the call.
#[no_mangle]
pub unsafe extern "C" fn c0c_subscribe(
    session: *const c0c_session,
    callback: c0c_event_cb,
    user: *mut c_void,
    out: *mut *mut c0c_subscription,
) -> i32 {
    if out.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *out = ptr::null_mut();
    }
    let Some(callback) = callback else {
        return C0C_E_INVALID_ARGUMENT;
    };
    if session.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let session_ref = unsafe { &*session };
    let result = catch_unwind(AssertUnwindSafe(
        || -> Result<*mut c0c_subscription, CError> {
            let subscription = {
                let inner = session_ref
                    .inner
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                inner
                    .sdk
                    .subscribe(EventFilter::all())
                    .map_err(|e| CError::from_sdk(&e))?
            };
            let stop = Arc::new(AtomicBool::new(false));
            let thread_stop = Arc::clone(&stop);
            let user = UserPtr(user);
            let handle = thread::Builder::new()
                .name("c0c-events".into())
                .spawn(move || event_loop(subscription, thread_stop, callback, user))
                .map_err(|error| CError::new(C0C_E_IO, format!("spawn event thread: {error}")))?;
            let thread = handle.thread().id();
            Ok(Box::into_raw(Box::new(c0c_subscription {
                stop,
                join: Mutex::new(Some(handle)),
                thread,
            })))
        },
    ));
    match result {
        Ok(Ok(handle)) => {
            unsafe {
                *out = handle;
            }
            C0C_OK
        }
        Ok(Err(error)) => {
            store_last(session, &error);
            error.code
        }
        Err(_) => {
            store_last(session, &CError::new(C0C_E_PANIC, "panic in c0c_subscribe"));
            C0C_E_PANIC
        }
    }
}

/// Stop a subscription and wait for any in-flight callback. Must not be called
/// from inside the callback itself.
#[no_mangle]
pub unsafe extern "C" fn c0c_unsubscribe(subscription: *mut c0c_subscription) -> i32 {
    if subscription.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let subscription = unsafe { Box::from_raw(subscription) };
    subscription.stop.store(true, Ordering::SeqCst);
    if subscription.thread != thread::current().id() {
        if let Some(handle) = subscription
            .join
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take()
        {
            let _ = handle.join();
        }
    }
    C0C_OK
}

/// Open a serial monitor on a managed port.
#[no_mangle]
pub unsafe extern "C" fn c0c_open_monitor(
    session: *const c0c_session,
    port: *const c_char,
    config: *const c0c_port_config,
    out: *mut *mut c0c_monitor,
) -> i32 {
    if out.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *out = ptr::null_mut();
    }
    if port.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let port_name = match c_str(port, "port")
        .and_then(|name| PortName::new(name).map_err(|e| CError::from_sdk(&e)))
    {
        Ok(name) => name,
        Err(error) => return error.code,
    };
    let config = if config.is_null() {
        PortConfig::default()
    } else {
        match port_config_from_c(unsafe { &*config }) {
            Ok(config) => config,
            Err(error) => return error.code,
        }
    };
    with_session(session, |inner| {
        let monitor = inner
            .sdk
            .open_monitor(&port_name, &config)
            .map_err(|e| CError::from_sdk(&e))?;
        unsafe {
            *out = Box::into_raw(Box::new(c0c_monitor {
                inner: Mutex::new(MonitorInner {
                    monitor,
                    pending: Vec::new(),
                }),
            }));
        }
        Ok(())
    })
}

/// Write bytes to the monitored port. `*written` is set to the count written.
#[no_mangle]
pub unsafe extern "C" fn c0c_monitor_write(
    monitor: *mut c0c_monitor,
    data: *const u8,
    len: usize,
    written: *mut usize,
) -> i32 {
    if written.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *written = 0;
    }
    if monitor.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    if data.is_null() && len > 0 {
        return C0C_E_INVALID_ARGUMENT;
    }
    let monitor = unsafe { &*monitor };
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut inner = monitor
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let slice = unsafe { std::slice::from_raw_parts(data, len) };
        match inner.monitor.write(slice) {
            Ok(count) => {
                unsafe {
                    *written = count;
                }
                C0C_OK
            }
            Err(error) => CError::from_sdk(&error).code,
        }
    }));
    result.unwrap_or(C0C_E_PANIC)
}

/// Read bytes with a timeout. Returns `C0C_OK` with `*read == 0` when the
/// timeout expires and no data arrived. A closed monitor returns `C0C_E_IO`.
#[no_mangle]
pub unsafe extern "C" fn c0c_monitor_read(
    monitor: *mut c0c_monitor,
    buffer: *mut u8,
    cap: usize,
    timeout_ms: u32,
    read: *mut usize,
) -> i32 {
    if read.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *read = 0;
    }
    if monitor.is_null() || buffer.is_null() || cap == 0 {
        return C0C_E_INVALID_ARGUMENT;
    }
    let monitor = unsafe { &*monitor };
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut inner = monitor
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let deadline = Instant::now() + Duration::from_millis(timeout_ms as u64);
        loop {
            if !inner.pending.is_empty() {
                let take = cap.min(inner.pending.len());
                unsafe {
                    ptr::copy_nonoverlapping(inner.pending.as_ptr(), buffer, take);
                    *read = take;
                }
                inner.pending.drain(..take);
                return C0C_OK;
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                return C0C_OK;
            }
            match inner.monitor.recv_timeout(remaining) {
                Ok(com0com_core::MonitorEvent::Data(data)) => {
                    inner.pending.extend_from_slice(&data)
                }
                Ok(com0com_core::MonitorEvent::Error(message)) => {
                    return CError::new(C0C_E_IO, message).code
                }
                Ok(com0com_core::MonitorEvent::Closed) => {
                    return CError::new(C0C_E_IO, "monitor closed").code
                }
                Err(RecvError::Timeout) | Err(RecvError::Empty) => return C0C_OK,
                Err(RecvError::Disconnected) => {
                    return CError::new(C0C_E_IO, "monitor closed").code
                }
            }
        }
    }));
    result.unwrap_or(C0C_E_PANIC)
}

/// Number of chunks dropped because the consumer fell behind.
#[no_mangle]
pub unsafe extern "C" fn c0c_monitor_dropped(monitor: *const c0c_monitor) -> u64 {
    if monitor.is_null() {
        return 0;
    }
    let monitor = unsafe { &*monitor };
    let inner = monitor
        .inner
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    inner.monitor.dropped()
}

/// Close a monitor and stop its reader thread.
#[no_mangle]
pub unsafe extern "C" fn c0c_monitor_close(monitor: *mut c0c_monitor) {
    if !monitor.is_null() {
        unsafe {
            drop(Box::from_raw(monitor));
        }
    }
}

/// Export the current pairs as JSON. `*len` receives the required byte count
/// including the trailing NUL.
#[no_mangle]
pub unsafe extern "C" fn c0c_state_export_json(
    session: *const c0c_session,
    buffer: *mut c_char,
    cap: usize,
    len: *mut usize,
) -> i32 {
    if len.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    unsafe {
        *len = 0;
    }
    with_session(session, |inner| {
        let json = inner
            .sdk
            .state()
            .export_json()
            .map_err(|e| CError::from_sdk(&e))?;
        let required = json.len() + 1;
        unsafe {
            *len = required;
        }
        if buffer.is_null() || cap < required {
            return Err(CError::new(
                C0C_E_BUFFER_TOO_SMALL,
                format!("buffer needs {required} bytes"),
            ));
        }
        unsafe {
            ptr::copy_nonoverlapping(json.as_ptr(), buffer.cast::<u8>(), json.len());
            *buffer.add(json.len()) = 0;
        }
        Ok(())
    })
}

/// Import a JSON snapshot and reconcile the backend with it. The report counts
/// applied and failed pairs; partial failures still return `C0C_OK`.
#[no_mangle]
pub unsafe extern "C" fn c0c_state_import_json(
    session: *const c0c_session,
    json: *const c_char,
    options: *const c0c_restore_options,
    report: *mut c0c_restore_report,
) -> i32 {
    if json.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    if !report.is_null() {
        unsafe {
            *report = c0c_restore_report::default();
        }
    }
    let text = match c_str(json, "json") {
        Ok(text) => text,
        Err(error) => return error.code,
    };
    let options = if options.is_null() {
        RestoreOptions::default()
    } else {
        restore_options_from_c(unsafe { &*options })
    };
    with_session(session, |inner| {
        let outcome = inner
            .sdk
            .state()
            .import_json(&text, options)
            .map_err(|e| CError::from_sdk(&e))?;
        if !report.is_null() {
            unsafe {
                *report = c0c_restore_report {
                    dry_run: outcome.dry_run as u32,
                    applied: outcome.applied.len() as u32,
                    failed: outcome.failed.len() as u32,
                };
            }
        }
        Ok(())
    })
}

/// Copy the last session error. Returns its code (`C0C_OK` when there is none).
#[no_mangle]
pub unsafe extern "C" fn c0c_session_last_error(
    session: *const c0c_session,
    error: *mut c0c_error,
) -> i32 {
    if session.is_null() || error.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let session = unsafe { &*session };
    let inner = session
        .inner
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    unsafe {
        *error = inner.last;
    }
    inner.last.code
}

/// Copy the last session error message (NUL-terminated UTF-8).
#[no_mangle]
pub unsafe extern "C" fn c0c_session_last_error_message(
    session: *const c0c_session,
    buffer: *mut c_char,
    cap: usize,
) -> i32 {
    if session.is_null() || buffer.is_null() {
        return C0C_E_INVALID_ARGUMENT;
    }
    let session = unsafe { &*session };
    let inner = session
        .inner
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let message = read_str(&inner.last.message).unwrap_or_default();
    let required = message.len() + 1;
    if cap < required {
        return C0C_E_BUFFER_TOO_SMALL;
    }
    unsafe {
        ptr::copy_nonoverlapping(message.as_ptr(), buffer.cast::<u8>(), message.len());
        *buffer.add(message.len()) = 0;
    }
    C0C_OK
}

pub const C0C_SIZEOF_C0C_PARAMS: usize = size_of::<c0c_params>();
pub const C0C_SIZEOF_C0C_PAIR_INFO: usize = size_of::<c0c_pair_info>();
pub const C0C_SIZEOF_C0C_PORT_INFO: usize = size_of::<c0c_port_info>();
pub const C0C_SIZEOF_C0C_DRIVER_DESC: usize = size_of::<c0c_driver_desc>();
pub const C0C_SIZEOF_C0C_LOG_ENTRY: usize = size_of::<c0c_log_entry>();
pub const C0C_SIZEOF_C0C_ERROR: usize = size_of::<c0c_error>();
pub const C0C_SIZEOF_C0C_PORT_CONFIG: usize = size_of::<c0c_port_config>();
pub const C0C_SIZEOF_C0C_RESTORE_OPTIONS: usize = size_of::<c0c_restore_options>();
pub const C0C_SIZEOF_C0C_RESTORE_REPORT: usize = size_of::<c0c_restore_report>();

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constants_are_stable() {
        assert_eq!(unsafe { c0c_api_version() }, 1);
        assert_eq!(C0C_OK, 0);
        assert_eq!(C0C_E_PANIC, -13);
        assert_eq!(C0C_E_BUFFER_TOO_SMALL, -12);
    }

    #[test]
    fn layout_is_stable() {
        assert_eq!(C0C_SIZEOF_C0C_PARAMS, 96);
        assert_eq!(C0C_SIZEOF_C0C_PAIR_INFO, 100);
        assert_eq!(C0C_SIZEOF_C0C_PORT_INFO, 268);
        assert_eq!(C0C_SIZEOF_C0C_DRIVER_DESC, 428);
        assert_eq!(C0C_SIZEOF_C0C_LOG_ENTRY, 300);
        assert_eq!(C0C_SIZEOF_C0C_ERROR, 264);
        assert_eq!(C0C_SIZEOF_C0C_PORT_CONFIG, 28);
        assert_eq!(C0C_SIZEOF_C0C_RESTORE_OPTIONS, 12);
        assert_eq!(C0C_SIZEOF_C0C_RESTORE_REPORT, 12);

        assert_eq!(std::mem::offset_of!(c0c_params, port_a), 0);
        assert_eq!(std::mem::offset_of!(c0c_params, port_b), 32);
        assert_eq!(std::mem::offset_of!(c0c_params, baud_emu), 64);
        assert_eq!(std::mem::offset_of!(c0c_params, pin_wiring_a), 88);
        assert_eq!(std::mem::offset_of!(c0c_pair_info, port_b), 36);
        assert_eq!(std::mem::offset_of!(c0c_driver_desc, sha256), 360);
    }

    #[test]
    fn params_convert_round_trip() {
        let params = PairParams {
            port_a: PortName::new("COM11").unwrap(),
            port_b: PortName::new("COM12").unwrap(),
            baud_emu: true,
            noise_enabled: true,
            noise_probability: 250,
            pin_wiring_a: PinWiring::NONE,
            ..PairParams::default()
        };
        let pod = c0c_params::from(&params);
        assert_eq!(read_str(&pod.port_a).unwrap(), "COM11");
        assert_eq!(pod.baud_emu, 1);
        assert_eq!(pod.noise_probability, 250);
        assert_eq!(params_from_c(&pod).unwrap(), params);
    }

    #[test]
    fn invalid_noise_is_rejected() {
        let pod = c0c_params {
            noise_probability: 10_001,
            ..c0c_params::default()
        };
        assert_eq!(
            params_from_c(&pod).unwrap_err().code,
            C0C_E_INVALID_ARGUMENT
        );
    }

    #[test]
    fn open_rejects_short_options() {
        let options = c0c_open_options {
            size: 4,
            ..c0c_open_options::default()
        };
        let mut session: *mut c0c_session = ptr::null_mut();
        assert_eq!(
            unsafe { c0c_open(&options, &mut session) },
            C0C_E_INVALID_ARGUMENT
        );
        assert!(session.is_null());
    }

    #[cfg(feature = "fake")]
    #[test]
    fn fake_session_crud_and_errors() {
        unsafe {
            let options = c0c_open_options {
                size: size_of::<c0c_open_options>() as u32,
                backend: C0C_BACKEND_FAKE,
                endpoint: ptr::null(),
            };
            let mut session: *mut c0c_session = ptr::null_mut();
            assert_eq!(c0c_open(&options, &mut session), C0C_OK);
            assert!(!session.is_null());

            let params = c0c_params::from(&PairParams {
                port_a: PortName::new("A").unwrap(),
                ..PairParams::default()
            });
            let mut info = c0c_pair_info::default();
            assert_eq!(
                c0c_create_pair(session, C0C_PAIR_ID_AUTO, &params, &mut info),
                C0C_OK
            );
            assert_eq!(info.id, 0);

            let mut count = 0usize;
            assert_eq!(
                c0c_list_pairs(session, ptr::null_mut(), 0, &mut count),
                C0C_E_BUFFER_TOO_SMALL
            );
            assert_eq!(count, 1);

            let mut error = c0c_error::default();
            assert_eq!(
                c0c_session_last_error(session, &mut error),
                C0C_E_BUFFER_TOO_SMALL
            );

            assert_eq!(
                c0c_create_pair(session, 0, &params, ptr::null_mut()),
                C0C_E_ALREADY_EXISTS
            );
            assert_eq!(c0c_remove_pair(session, 9), C0C_E_NOT_FOUND);

            assert_eq!(c0c_session_last_error(session, &mut error), C0C_E_NOT_FOUND);
            assert_eq!(read_str(&error.message).unwrap(), "pair not found");

            let mut message = vec![0 as c_char; C0C_MESSAGE_MAX];
            assert_eq!(
                c0c_session_last_error_message(session, message.as_mut_ptr(), message.len()),
                C0C_OK
            );
            assert_eq!(read_str(&message).unwrap(), "pair not found");

            c0c_close(session);
        }
    }
}
